changeSet.sql:
CREATE UNIQUE INDEX idx_shoutouts_single_active
ON player_shoutouts (player_id)
WHERE is_active = true;

ALTER TABLE player_shoutouts ENABLE ROW LEVEL SECURITY;

-- Anyone can read active shout-outs
CREATE POLICY "shoutouts_select_active"
  ON player_shoutouts FOR SELECT
  USING (is_active = true);

-- Players can manage their own shout-outs
CREATE POLICY "shoutouts_insert_own"
  ON player_shoutouts FOR INSERT
  WITH CHECK (
    player_id IN (
      SELECT id FROM player_profiles WHERE user_id = auth.uid()
    )
  );

CREATE POLICY "shoutouts_update_own"
  ON player_shoutouts FOR UPDATE
  USING (
    player_id IN (
      SELECT id FROM player_profiles WHERE user_id = auth.uid()
    )
  );

CREATE POLICY "shoutouts_delete_own"
  ON player_shoutouts FOR DELETE
  USING (
    player_id IN (
      SELECT id FROM player_profiles WHERE user_id = auth.uid()
    )
  );

changeSet.rollback:
DROP POLICY IF EXISTS "shoutouts_delete_own" ON player_shoutouts;
DROP POLICY IF EXISTS "shoutouts_update_own" ON player_shoutouts;
DROP POLICY IF EXISTS "shoutouts_insert_own" ON player_shoutouts;
DROP POLICY IF EXISTS "shoutouts_select_active" ON player_shoutouts;
